function fk(n, start, end) {
  const fact = [1];
  for (let i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
  const perm = new Int32Array(n), p = new Int32Array(n), count = new Int32Array(n), tmp = new Int32Array(n);
  for (let i = 0; i < n; i++) perm[i] = i;
  let idx = start;
  for (let i = n - 1; i > 0; i--) {
    const d = Math.floor(idx / fact[i]);
    idx = idx % fact[i];
    count[i] = d;
    for (let j = 0; j <= i; j++) tmp[j] = perm[j];
    for (let j = 0; j <= i; j++) perm[j] = tmp[(j + d) % (i + 1)];
  }
  let checksum = 0, maxFlips = 0;
  for (let index = start; index < end; index++) {
    let k = perm[0];
    if (k !== 0) {
      for (let i = 1; i < n; i++) p[i] = perm[i];
      let flips = 0;
      while (k !== 0) {
        let i = 1, j = k - 1;
        while (i < j) { const t = p[i]; p[i] = p[j]; p[j] = t; i++; j--; }
