traces.inference_trace:
The program writes to a large output buffer and makes as few calls as possible, because the output is about 10N bytes (roughly 250 MB at N = 25,000,000).

1. **Precomputed symbol table.** The generator only ever produces seeds in 0 to 139967. So for each table I compute the symbol for every possible seed once, giving a 139,968-byte lookup table.
   - Each entry uses the same rule as the spec: cumulative probabilities summed as doubles in order, and the first symbol whose cumulative value is strictly greater than `seed / 139968`.
   - Each draw then costs one integer step of the generator plus one table lookup, with no floating-point comparisons in the hot loop.
   - `seed * 3877` stays below 2^31, so the plain integer arithmetic is exact.
2. **ALU section.** I double the ALU string so any 60-character line is one contiguous slice that can be copied directly.
3. **Output.** Lines are built in a 1 MB buffer and flushed to file descriptor 1 with `writeSync`. If the pipe is busy (`EAGAIN`), the write is retried.

```typescript
import * as fs from 'fs';

const N = parseInt(process.argv[2], 10);

const BUF_SIZE = 1 << 20;
const out = Buffer.allocUnsafe(BUF_SIZE);
let pos = 0;

function flush(): void {
  let off = 0;
  while (off < pos) {
    try {
      off += fs.writeSync(1, out, off, pos - off);
    } catch (e: any) {
      if (e && e.code === 'EAGAIN') continue;
      throw e;
    }
  }
  pos = 0;
}

function writeStr(s: string): void {
  if (pos + s.length + 1 > BUF_SIZE) flush();
  pos += out.write(s, pos, 'latin1');
}

const ALU =
  'GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA' +
  'TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT' +
  'AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG' +
  'GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG' +
  'CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA';

const LINE = 60;
const IM = 139968, IA = 3877, IC = 29573;
let seed = 42;

function repeatFasta(header: string, n: number): void {
  writeStr(header + '\n');
  const L = ALU.length;
  const dbl = Buffer.from(ALU + ALU, 'latin1');
  let k = 0;
  let rem = n;
  while (rem > 0) {
    const len = rem < LINE ? rem : LINE;
    if (pos + len + 1 > BUF_SIZE) flush();
    dbl.copy(out, pos, k, k + len);
    pos += len;
    out[pos++] = 10;
    k += len;
    if (k >= L) k -= L;
    rem -= len;
  }
}

function buildTable(syms: string, probs: number[]): Uint8Array {
  const cum: number[] = [];
  let acc = 0;
  for (let i = 0; i < probs.length; i++) {
    acc += probs[i];
    cum.push(acc);
  }
  const tbl = new Uint8Array(IM);
  const codes = syms.split('').map(c => c.charCodeAt(0));
  for (let s = 0; s < IM; s++) {
    const r = s / IM;
    let idx = codes.length - 1;
    for (let i = 0; i < cum.length; i++) {
      if (cum[i] > r) { idx = i; break; }
    }
    tbl[s] = codes[idx];
  }
  return tbl;
}

function randomFasta(header: string, tbl: Uint8Array, n: number): void {
  writeStr(header + '\n');
  let s = seed;
  let rem = n;
  const o = out;
  while (rem > 0) {
    const len = rem < LINE ? rem : LINE;
    if (pos + len + 1 > BUF_SIZE) flush();
    let p = pos;
    const end = p + len;
    while (p < end) {
      s = (s * IA + IC) % IM;
      o[p++] = tbl[s];
    }
    o[p++] = 10;
    pos = p;
    rem -= len;
  }
  seed = s;
}

repeatFasta('>ONE Homo sapiens alu', 2 * N);

const iubTbl = buildTable('acgtBDHKMNRSVWY', [
  0.27, 0.12, 0.12, 0.27,
  0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02,
]);
randomFasta('>TWO IUB ambiguity codes', iubTbl, 3 * N);

const homoTbl = buildTable('acgt', [
  0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008,
]);
randomFasta('>THREE Homo sapiens frequency', homoTbl, 5 * N);

flush();
```

