traces.inference_trace:
The program reads all of stdin at once, then handles each FASTA record in order:

1. **Header:** each line starting with `>` is copied to the output unchanged.
2. **Sequence:** the lines that follow are joined with the newlines removed.
3. **Reverse-complement:** the joined bases are read from the end to the start, and each base is mapped through a 256-entry lookup table.
4. **Re-wrap:** the result is written as lines of 60 characters.

The program assumes a fixed width of 60 rather than measuring the input's line length, because that is the width the benchmark's `fasta` generator emits. If the input could use a different width, the code would need to detect it from the first sequence line.

**Complement table:**
- It follows the IUPAC mapping given in the problem.
- Lowercase input is complemented to uppercase.
- Any other byte passes through unchanged.

**Input/output:**
- Stdin is read in chunks with `readSync`, and `EAGAIN` is retried so piped input works.
- The output goes into one preallocated buffer, sized to cover any trailing newlines the program adds.
- That buffer is written with a `writeSync` loop.

```typescript
import * as fs from "fs";

function readAll(): Buffer {
  const chunks: Buffer[] = [];
  let total = 0;
  const bufSize = 1 << 20;
  while (true) {
    const b = Buffer.allocUnsafe(bufSize);
    let n = 0;
    try {
      n = fs.readSync(0, b, 0, bufSize, null);
    } catch (e: any) {
      if (e.code === "EAGAIN") continue;
      if (e.code === "EOF") break;
      throw e;
    }
    if (n <= 0) break;
    chunks.push(n === bufSize ? b : b.subarray(0, n));
    total += n;
  }
  return Buffer.concat(chunks, total);
}

function main() {
  const _n = parseInt(process.argv[2] || "0", 10);
  const input = readAll();
  const len = input.length;

  const tbl = new Uint8Array(256);
  for (let i = 0; i < 256; i++) tbl[i] = i;
  const pairs: [string, string][] = [
    ["A", "T"], ["C", "G"], ["G", "C"], ["T", "A"], ["U", "A"],
    ["M", "K"], ["R", "Y"], ["W", "W"], ["S", "S"], ["Y", "R"],
    ["K", "M"], ["V", "B"], ["H", "D"], ["D", "H"], ["B", "V"], ["N", "N"],
  ];
  for (const [a, b] of pairs) {
    tbl[a.charCodeAt(0)] = b.charCodeAt(0);
    tbl[a.toLowerCase().charCodeAt(0)] = b.charCodeAt(0);
  }

  const out = Buffer.allocUnsafe(len + Math.floor(len / 60) + 4096);
  let op = 0;
  const seq = Buffer.allocUnsafe(len + 1);

  let i = 0;
  while (i < len) {
    if (input[i] === 62) { // '>'
      let e = input.indexOf(10, i);
      if (e < 0) e = len;
      input.copy(out, op, i, e);
      op += e - i;
      out[op++] = 10;
      i = e + 1;
      // gather sequence
      let sl = 0;
      while (i < len && input[i] !== 62) {
        const c = input[i++];
        if (c !== 10 && c !== 13) seq[sl++] = c;
      }
      // write reverse complement with 60-wide lines
      let k = sl - 1;
      while (k >= 0) {
        let cnt = k + 1 < 60 ? k + 1 : 60;
        while (cnt-- > 0) out[op++] = tbl[seq[k--]];
        out[op++] = 10;
      }
    } else {
      i++;
    }
  }

  let off = 0;
  while (off < op) {
    try {
      off += fs.writeSync(1, out, off, op - off);
    } catch (e: any) {
      if (e.code !== "EAGAIN") throw e;
    }
  }
}

main();
```

